# Top-level guard: any unhandled exception returns structured JSON
# so the Respond node always fires and the frontend shows the error.
try:
    import sys, os, json, re
    sys.path.insert(0, '/data/scripts')
    import requests as req
    # One definition of what an ownership edge means and what it is worth,
    # shared with WF13's writer and WF04's reader. Re-declaring either inline
    # here is what check_asset_ownership_catalog() fails on.
    from asset_ownership import OWNERSHIP_LABELS, asset_bump as _asset_bump

    # ── credentials ───────────────────────────────────────────────────────────────
    FLOWSINT_URL  = os.environ.get('FLOWSINT_API_URL', 'http://flowsint-api:5001')
    FLOWSINT_KEY  = os.environ.get('FLOWSINT_API_KEY', '')
    SKETCH_ID = os.environ.get('FLOWSINT_SKETCH_ID', '')
    _sb = _items[0].get('json', {}) if _items else {}
    _sb = _sb.get('body', _sb) if isinstance(_sb.get('body'), dict) else _sb
    SKETCH_ID = _sb.get('sketch_id') or SKETCH_ID
    OLLAMA_URL    = os.environ.get('OLLAMA_URL', 'http://llm-gateway:8080')
    SEC_LLM_MODEL = os.environ.get('SECURITY_LLM_MODEL', 'qwen3.8:27b')

    # ── parse webhook body ────────────────────────────────────────────────────────
    item = _items[0].get('json', {}) if _items else {}
    body = item.get('body', item) if isinstance(item.get('body'), dict) else item

    campaign_id       = body.get('campaign_id', '')
    campaign_name     = body.get('campaign_name', campaign_id)
    target_type       = body.get('target_type', 'individual')
    target_name       = body.get('target_name', '')
    additional_ids    = body.get('additional_ids', '')
    company_email     = body.get('company_email', '')
    company_domain    = body.get('company_email_domain', '')
    mission_statement = body.get('mission_statement', '')

    # ── operator tags from the Targets tab (Compromised / Of Interest) ────────────
    # These marks live only in the operator's browser localStorage, so the frontend
    # ships them in the request body — the graph carries no trace of them. They are
    # human ground truth (a foothold we already own, a person the operator cares
    # about) and outrank the heuristic scoring below.
    def _tag_keys(v):
        if isinstance(v, dict):
            v = list(v.keys())
        if not isinstance(v, list):
            return []
        return [str(k).strip() for k in v[:400] if str(k or '').strip()]

    _op_tags     = body.get('operator_tags') or {}
    if not isinstance(_op_tags, dict):
        _op_tags = {}
    _op_comp_in  = _tag_keys(_op_tags.get('compromised'))
    _op_oi_in    = _tag_keys(_op_tags.get('of_interest'))
    _op_comp_set = {k.lower() for k in _op_comp_in}
    _op_oi_set   = {k.lower() for k in _op_oi_in}
    # lowercased key -> the operator's original spelling, so an unmatched mark is
    # reported back the way it reads in the Targets tab.
    _op_orig     = {k.lower(): k for k in (_op_comp_in + _op_oi_in)}
    _op_matched  = set()   # lowercased tag keys that resolved to an individual
    # Out-of-scope marks: entities the operator excluded from the engagement.
    # These are dropped from the graph population entirely below — not scored,
    # not ranked, not surfaced in targets/scenarios/breach/credential output —
    # so they never reach the analysis LLM at all.
    _op_oos_in      = _tag_keys(_op_tags.get('out_of_scope'))
    _op_oos_set     = {k.lower() for k in _op_oos_in}
    _op_oos_orig    = {k.lower(): k for k in _op_oos_in}
    _op_oos_matched = set()
    # Device marks are a separate namespace (keyed by hostname, not person name).
    _op_dev      = _op_tags.get('devices') or {}
    if not isinstance(_op_dev, dict):
        _op_dev = {}
    _opd_comp_in = _tag_keys(_op_dev.get('compromised'))
    _opd_oi_in   = _tag_keys(_op_dev.get('of_interest'))
    _opd_comp_set = {k.lower() for k in _opd_comp_in}
    _opd_oi_set   = {k.lower() for k in _opd_oi_in}
    _opd_orig     = {k.lower(): k for k in (_opd_comp_in + _opd_oi_in)}
    _opd_matched  = set()  # lowercased tag keys that resolved to a device
    _opd_oos_in      = _tag_keys(_op_dev.get('out_of_scope'))
    _opd_oos_set     = {k.lower() for k in _opd_oos_in}
    _opd_oos_orig    = {k.lower(): k for k in _opd_oos_in}
    _opd_oos_matched = set()
    # False-positive marks: results the operator judged WRONG — a mis-scored person,
    # a host that is not what the graph claims, an asset that is not ours. Dropped
    # exactly like out_of_scope (not scored, not ranked, absent from the targets,
    # scenarios and rollups), but tracked under its own key so the echo can say
    # which judgement excluded what: "not in this engagement" and "this result is
    # wrong" are different facts and the operator acts on them differently.
    _op_fp_in       = _tag_keys(_op_tags.get('false_positive'))
    _op_fp_set      = {k.lower() for k in _op_fp_in}
    _op_fp_orig     = {k.lower(): k for k in _op_fp_in}
    _op_fp_matched  = set()
    _opd_fp_in      = _tag_keys(_op_dev.get('false_positive'))
    _opd_fp_set     = {k.lower() for k in _opd_fp_in}
    _opd_fp_orig    = {k.lower(): k for k in _opd_fp_in}
    _opd_fp_matched = set()

    # ── fetch graph directly from Neo4j (bypasses 577 MB Flowsint API response) ─
    import base64 as _b64
    _NEO_URL = os.environ.get('NEO4J_HTTP_URL', 'http://flowsint-neo4j-prod:7474').rstrip('/')
    _NEO_USER = os.environ.get('NEO4J_USER', 'neo4j')
    _NEO_PASS = os.environ.get('NEO4J_PASSWORD', '')
    _NEO_AUTH = _b64.b64encode(f'{_NEO_USER}:{_NEO_PASS}'.encode()).decode()
    _NEO_H = {'Authorization': f'Basic {_NEO_AUTH}', 'Content-Type': 'application/json'}

    def _cypher(stmt, params=None):
        _r = req.post(f'{_NEO_URL}/db/neo4j/tx/commit', headers=_NEO_H,
                      json={'statements': [{'statement': stmt, 'parameters': params or {}}]}, timeout=120)
        _r.raise_for_status()
        _d = _r.json()
        if _d.get('errors'):
            raise RuntimeError(_d['errors'][0].get('message', str(_d['errors'])))
        cols = _d['results'][0]['columns']
        return [dict(zip(cols, row['row'])) for row in _d['results'][0].get('data', [])]

    def _props_to_nd(eid, props):
        np = {}
        for k, v in props.items():
            if k.startswith('nodeProperties.'):
                np[k[15:]] = v
        return {'id': eid, 'nodeType': props.get('nodeType', ''), 'nodeLabel': props.get('nodeLabel', ''), 'nodeProperties': np}

    try:
        _LABELS = ['individual', 'device', 'organization', 'gpo', 'Subdomain', 'CloudAsset', 'Service', 'DomainBreach', 'WebAsset', 'FlareBreach', 'credential', 'socialprofile', 'SocialProfile']
        nds = []
        for _lbl in _LABELS:
            for _row in _cypher(f'MATCH (n:`{_lbl}` {{sketch_id: $sid}}) WHERE n.deleted_at IS NULL RETURN elementId(n) AS eid, properties(n) AS p', {'sid': SKETCH_ID}):
                nds.append(_props_to_nd(_row['eid'], _row['p']))
        rls = []
        for _lbl in _LABELS:
            for _row in _cypher(f'MATCH (a:`{_lbl}` {{sketch_id: $sid}})-[r]->(b) WHERE b.sketch_id = $sid AND r.deleted_at IS NULL RETURN elementId(a) AS s, elementId(b) AS t, type(r) AS l', {'sid': SKETCH_ID}):
                rls.append({'source': _row['s'], 'target': _row['t'], 'label': _row['l']})
    except Exception as e:
        return [{'json': {'error': f'Neo4j graph fetch failed: {e}', 'targets': [], 'device_targets': [], 'scenarios': [], 'summary': '', 'individuals_count': 0}}]

    nodes_by_id = {n['id']: n for n in nds}

    # ── External attack surface from Domain Recon assets ──────────────────────
    ASSET_TYPES = {'webasset', 'cloudasset', 'service', 'subdomain'}
    assets_by_id = {}
    for _an in nds:
        if (_an.get('nodeType') or '').lower() in ASSET_TYPES:
            assets_by_id[_an['id']] = {'type': _an.get('nodeType'), 'label': _an.get('nodeLabel', ''),
                                       'props': _an.get('nodeProperties') or {}}
    owned_assets = {}        # individual node id -> [asset dicts]
    asset_owner_names = {}   # asset node id -> [individual labels]
    # The ownership vocabulary and its weights come from scripts/asset_ownership.py,
    # not from a literal set here. This section RENDERS every class -- an operator
    # wants to see the registrant relationship -- but asset_bump below weights
    # them, because they are not equally good evidence:
    #
    #   OWNS_ASSET   AD control over the device serving the asset, or a cloud IAM
    #                permission on the resource. Asset-scoped. Scores.
    #   HAS_ACCESS   AD reach without control (CanRDP, session). Scores less.
    #   MANAGES      the apex WHOIS registrant. Computed once and attached to the
    #                apex, every subdomain and every bucket in a sweep alike, so
    #                it is a fact about the DOMAIN. Weighted 0.
    #
    # WF13 emits exactly one label per relationship, so asset_bump cannot
    # double-count.
    OWN_LABELS = set(OWNERSHIP_LABELS)
    for _ae in rls:
        if _ae.get('label') in OWN_LABELS:
            _a = assets_by_id.get(_ae.get('target', ''))
            if _a:
                # The label is the only durable carrier of evidence strength:
                # Flowsint drops edge `data` before it reaches Neo4j, so the
                # relationship type is what the weighting has to read.
                owned_assets.setdefault(_ae.get('source', ''), []).append(
                    dict(_a, relationship=_ae.get('label')))
                _ilbl = nodes_by_id.get(_ae.get('source', ''), {}).get('nodeLabel', '')
                if _ilbl:
                    asset_owner_names.setdefault(_ae.get('target', ''), []).append(_ilbl)

    # ── LinkedIn profile index: individual label → {url, job_title, employer} ─────
    _li_profiles = {}
    _sp_by_id = {}
    for _n in nds:
        _nt = (_n.get('nodeType') or _n.get('data', {}).get('type') or '').lower()
        if _nt == 'socialprofile':
            _np = _n.get('nodeProperties') or _n.get('data') or {}
            if (_np.get('platform') or '').lower() == 'linkedin':
                _sp_by_id[_n['id']] = {
                    'url':       _np.get('url') or '',
                    'job_title': _np.get('job_title'),
                    'employer':  _np.get('employer'),
                }
    for _e in rls:
        if _e.get('label') != 'HAS_PROFILE':
            continue
        _src = nodes_by_id.get(_e.get('source', ''), {})
        if (_src.get('nodeType') or '').lower() != 'individual':
            continue
        _li_d = _sp_by_id.get(_e.get('target', ''))
        if _li_d:
            _il = _src.get('nodeLabel') or ''
            if _il and _il not in _li_profiles:
                _li_profiles[_il] = _li_d

    # ── truthy coercion (Flowsint/Neo4j booleans may arrive as bool or "true") ────
    def _is_true(v):
        return v is True or v == 1 or (isinstance(v, str) and v.strip().lower() in ('true', '1', 'yes'))

    # ── Flare breach + Titus credential node indexes ──────────────────────────────
    # The Flare results (FlareBreach nodes) and confirmed/compromised credentials
    # (credential nodes) are linked to Individuals via HAS_BREACH / HAS_CREDENTIAL.
    # Index the nodes by id, then group them per-individual by walking the edges so
    # the analysis can reason about credential-to-user relationships directly rather
    # than the pre-aggregated counts on the Individual node alone.
    _breach_nodes = {}   # node id -> FlareBreach props
    _cred_nodes   = {}    # node id -> credential props
    for _n in nds:
        _nt = (_n.get('nodeType') or _n.get('data', {}).get('type') or '').lower()
        if _nt == 'flarebreach':
            _breach_nodes[_n['id']] = _n.get('nodeProperties') or _n.get('data') or {}
        elif _nt == 'credential':
            _cred_nodes[_n['id']] = _n.get('nodeProperties') or _n.get('data') or {}
    ind_breaches = {}    # individual node id -> [FlareBreach props]
    ind_creds    = {}    # individual node id -> [credential props]
    for _e in rls:
        _elbl = _e.get('label')
        _esrc = _e.get('source', '')
        _etgt = _e.get('target', '')
        if _elbl == 'HAS_BREACH' and _etgt in _breach_nodes:
            ind_breaches.setdefault(_esrc, []).append(_breach_nodes[_etgt])
        elif _elbl == 'HAS_CREDENTIAL' and _etgt in _cred_nodes:
            ind_creds.setdefault(_esrc, []).append(_cred_nodes[_etgt])

    # Severity → weight for deriving a credential contribution straight from the
    # linked credential nodes (works even if the credential_enricher hasn't run).
    _CRED_SEV_W = {'critical': 12, 'high': 8, 'medium': 4, 'low': 2, 'info': 1}

    # ── ACE weights ───────────────────────────────────────────────────────────────
    ACE_SCORES = {
        'GenericAll': 10, 'WriteDacl': 9, 'WriteOwner': 8,
        'GenericWrite': 7, 'AllExtendedRights': 7, 'AddAllowedToAct': 7,
        'ForceChangePassword': 6, 'AddMember': 5, 'Owns': 5,
        'WriteAccountRestrictions': 5, 'AddKeyCredentialLink': 5,
        'ReadLAPSPassword': 4, 'WriteSPN': 4, 'ReadGMSAPassword': 4,
        'GetChanges': 4, 'DCSync': 10, 'GetChangesAll': 10,
    }
    DA_PATTERN = ('domain admins', 'enterprise admins', 'schema admins')

    _edges_by_src = {}
    for _e in rls:
        _edges_by_src.setdefault(_e.get('source', ''), []).append(_e)

    # ── score every individual in Python — no LLM needed for ranking ─────────────
    individuals = []
    for node in nds:
        ntype = (node.get('nodeType') or node.get('data', {}).get('type') or '').lower()
        if ntype != 'individual':
            continue

        props          = node.get('nodeProperties') or node.get('data') or {}
        label          = node.get('nodeLabel') or props.get('label') or props.get('full_name') or ''
        base_score     = int(props.get('priority_score') or props.get('ad_max_score') or props.get('attack_score') or 0)
        is_admin       = bool(props.get('is_admin'))
        has_beacon     = bool(props.get('active_beacon'))
        breach_count   = int(props.get('breach_count') or 0)
        has_stealer    = bool(props.get('has_stealer_log'))
        flare_run      = bool(props.get('flare_run'))
        raw_pe         = props.get('personal_emails') or '[]'
        try:
            personal_emails = json.loads(raw_pe) if isinstance(raw_pe, str) else (raw_pe if isinstance(raw_pe, list) else [])
        except Exception:
            personal_emails = []

        # Operator marks are keyed by the Targets-tab row label (the nodeLabel), but
        # match SAM/username/email too so a differently-keyed mark still lands.
        _aliases = {str(_a).strip().lower() for _a in (
            label, props.get('sam_account_name'), props.get('username'),
            props.get('email'), props.get('full_name')) if _a}
        _hit_oos       = _aliases & _op_oos_set
        _hit_fp        = _aliases & _op_fp_set
        if _hit_oos or _hit_fp:
            _op_oos_matched |= _hit_oos
            _op_fp_matched  |= _hit_fp
            continue   # excluded: not scored, not output, not in the scenarios
        _hit_comp      = _aliases & _op_comp_set
        _hit_oi        = _aliases & _op_oi_set
        op_compromised = bool(_hit_comp)
        op_of_interest = bool(_hit_oi)
        _op_matched |= _hit_comp | _hit_oi

        # ── Flare breaches + confirmed/compromised credentials for this person ──
        # Alert flags set by the FlareBreach + Credential enrichers.
        _alert_raw = props.get('alert') or ''
        alert_flags = ([a.strip() for a in _alert_raw.split(',') if a.strip()]
                       if isinstance(_alert_raw, str)
                       else (_alert_raw if isinstance(_alert_raw, list) else []))

        my_breaches = ind_breaches.get(node['id'], [])
        my_creds    = ind_creds.get(node['id'], [])

        # Breach detail: event-type breakdown, stealer malware, plaintext exposure.
        breach_events, stealer_malware = {}, []
        plaintext_exposed = False
        for _b in my_breaches:
            _et = _b.get('event_type') or 'leaked_credentials'
            breach_events[_et] = breach_events.get(_et, 0) + 1
            if _is_true(_b.get('password_exposed')) or (str(_b.get('hash_type') or '').lower() in ('plain', 'plaintext')):
                plaintext_exposed = True
            if 'stealer' in _et:
                _mf = _b.get('malware_family')
                if _mf:
                    stealer_malware.append(str(_mf))
        # Fall back to the aggregated count when no breach nodes were traversed.
        breach_count = len(my_breaches) if my_breaches else breach_count

        # Credential detail: confirmed-compromised = credential.validated == true.
        validated_creds = [c for c in my_creds if _is_true(c.get('validated'))]
        validated_cred_count = len(validated_creds)
        cred_services = sorted({str(c.get('service')) for c in my_creds if c.get('service')})
        cred_types    = sorted({str(c.get('cred_type')) for c in my_creds if c.get('cred_type')})
        _cred_sevs    = [(c.get('severity') or 'info') for c in my_creds]
        cred_severity = ''
        if _cred_sevs:
            cred_severity = max(_cred_sevs, key=lambda s: _CRED_SEV_W.get(str(s).lower(), 0))
        # Derive a credential score straight from the linked nodes, then take the
        # max with the enricher's cred_score so it works with or without the enricher.
        raw_cred_bump = 0
        for c in my_creds:
            _cw = _CRED_SEV_W.get(str(c.get('severity') or 'info').lower(), 1)
            if _is_true(c.get('validated')):
                _cw += 6
            raw_cred_bump = max(raw_cred_bump, _cw)
        if validated_cred_count > 1:
            raw_cred_bump += (validated_cred_count - 1) * 2
        cred_bump = min(28, max(int(props.get('cred_score') or 0), raw_cred_bump))

        has_reuse = ('PASSWORD_REUSE' in alert_flags)
        # Validated credential AND a corporate Flare breach on the same person is
        # the highest-confidence compromise signal (mirrors CORP_BREACH_CRED_MATCH).
        breach_cred_match = ('CORP_BREACH_CRED_MATCH' in alert_flags) or (
            validated_cred_count > 0 and (len(my_breaches) > 0 or breach_count > 0))
        has_stealer = has_stealer or any('stealer' in _et for _et in breach_events)
        # Confirmed compromised credentials we actually hold on this user.
        confirmed_compromised = bool(validated_cred_count or has_stealer or plaintext_exposed)

        # Technology context
        raw_ts = props.get('tech_stack') or '[]'
        try:
            tech_stack = json.loads(raw_ts) if isinstance(raw_ts, str) else (raw_ts if isinstance(raw_ts, list) else [])
        except Exception:
            tech_stack = []
        tech_risk_score = float(props.get('tech_risk_score') or 0)
        os_risk = props.get('os_risk') or 'unknown'
        relevant_cves_raw = props.get('relevant_cves') or '[]'
        try:
            relevant_cves = json.loads(relevant_cves_raw) if isinstance(relevant_cves_raw, str) else (relevant_cves_raw if isinstance(relevant_cves_raw, list) else [])
        except Exception:
            relevant_cves = []
        mitre_techniques_raw = props.get('mitre_techniques') or '[]'
        try:
            mitre_techniques = json.loads(mitre_techniques_raw) if isinstance(mitre_techniques_raw, str) else (mitre_techniques_raw if isinstance(mitre_techniques_raw, list) else [])
        except Exception:
            mitre_techniques = []

        groups, top_aces = [], []
        for edge in _edges_by_src.get(node['id'], []):
            el    = edge.get('label', '')
            tgt   = nodes_by_id.get(edge.get('target', ''), {})
            tp    = tgt.get('nodeProperties') or tgt.get('data') or {}
            tlbl  = tgt.get('nodeLabel') or tp.get('label') or tp.get('name') or ''
            if el == 'MEMBER_OF' and tlbl:
                groups.append(tlbl)
            elif el in ACE_SCORES:
                top_aces.append({'right': el, 'target': tlbl, 'score': ACE_SCORES[el]})

        in_da = any(any(p in g.lower() for p in DA_PATTERN) for g in groups)
        top_aces.sort(key=lambda x: -x['score'])

        my_assets = owned_assets.get(node['id'], [])
        # Weighted by evidence tier and CAPPED, via the shared helper.
        #
        # This used to add a flat 8 per owned asset with no discrimination and no
        # ceiling, over a label set that included the domain registrant. A
        # registrant on a 40-subdomain estate therefore accumulated +320 and
        # pegged the 100 cap -- which is how WF13's retired name-token false
        # positives actually moved Targets-tab scores. Registrant rows now
        # contribute 0 and still render; an operator who genuinely admins six
        # hosts contributes ASSET_BUMP_CAP rather than 48, the same
        # "MAX over an owner's assets, not a sum" rule WF04 already applies.
        _bump_rows = []
        for _ma in my_assets:
            _mv = _ma['props'].get('vulns') or '[]'
            try:
                _has_vulns = isinstance(_mv, str) and len(json.loads(_mv)) > 0
            except Exception:
                _has_vulns = False
            _bump_rows.append({'relationship': _ma.get('relationship') or '',
                               'type': _ma.get('type') or '',
                               'has_vulns': _has_vulns})
        asset_bump = _asset_bump(_bump_rows)
        # Composite score (capped 100)
        tech_bump = min(15, int(tech_risk_score / 5))
        # Credential / breach contributions: cred_bump already blends severity +
        # validated count; breach_cred_bump is the strongest (validated cred on a
        # breached corp account); the rest cover reuse, non-stealer breach exposure,
        # and plaintext-password leakage. has_stealer keeps its own +15 above.
        breach_cred_bump = 18 if breach_cred_match else 0
        reuse_bump       = 5 if has_reuse else 0
        breach_bump      = 0 if has_stealer else min(10, breach_count * 2)
        plaintext_bump   = 8 if plaintext_exposed else 0
        # Operator judgement: a hand-marked compromise is ground truth the graph
        # does not carry; Of Interest is a stated mission priority.
        op_bump          = (30 if op_compromised else 0) + (12 if op_of_interest else 0)
        score = min(100, base_score
            + (40 if is_admin    else 0)
            + (20 if has_beacon  else 0)
            + (15 if has_stealer else 0)
            + (25 if in_da       else 0)
            + (top_aces[0]['score'] * 2 if top_aces else 0)
            + asset_bump
            + tech_bump
            + cred_bump
            + breach_cred_bump
            + reuse_bump
            + breach_bump
            + plaintext_bump
            + op_bump)

        # Human-readable rationale built from facts
        reasons = []
        if op_compromised: reasons.append('OPERATOR-MARKED COMPROMISED')
        if op_of_interest: reasons.append('OPERATOR-MARKED OF INTEREST')
        if is_admin:    reasons.append('local admin')
        if in_da:       reasons.append('DA/EA member')
        if has_beacon:  reasons.append('active C2 beacon')
        if has_stealer: reasons.append('stealer log hit')
        if top_aces:    reasons.append(f'{top_aces[0]["right"]} on {top_aces[0]["target"]}')
        if validated_cred_count:
            reasons.append(f'{validated_cred_count} CONFIRMED credential(s)' + (' (' + ', '.join(cred_services[:3]) + ')' if cred_services else ''))
        elif my_creds:
            reasons.append(f'{len(my_creds)} credential(s)' + (' (' + ', '.join(cred_services[:3]) + ')' if cred_services else ''))
        if breach_cred_match: reasons.append('validated cred x corp breach')
        if has_reuse:         reasons.append('password reuse')
        if plaintext_exposed: reasons.append('plaintext password exposed')
        if breach_events:
            reasons.append('breaches: ' + ', '.join(f'{k}x{v}' for k, v in breach_events.items())
                           + (' [' + ', '.join(sorted(set(stealer_malware))[:2]) + ']' if stealer_malware else ''))
        elif breach_count:
            reasons.append(f'{breach_count} breach(es)')
        if my_assets:
            _anames = ', '.join(sorted({a['label'] for a in my_assets})[:3])
            reasons.append('manages ' + str(len(my_assets)) + ' external asset(s): ' + _anames)
        if tech_stack:
            reasons.append(f'{len(tech_stack)} tech item(s)')
        if tech_risk_score > 0:
            reasons.append(f'tech risk {tech_risk_score:.1f}')
        if relevant_cves:
            reasons.append(f'{len(relevant_cves)} relevant CVE(s)')
        rationale = ', '.join(reasons) if reasons else f'base AD score {base_score}'

        _li = _li_profiles.get(label, {})
        individuals.append({
            'label': label, 'score': score, 'rationale': rationale,
            'op_compromised': op_compromised, 'op_of_interest': op_of_interest,
            'is_admin': is_admin, 'has_beacon': has_beacon,
            'has_stealer': has_stealer, 'in_da': in_da,
            'top_ace': top_aces[0] if top_aces else None,
            'groups': groups[:3],
            'breach_count': breach_count,
            'breach_events': breach_events,
            'stealer_malware': sorted(set(stealer_malware)),
            'plaintext_exposed': plaintext_exposed,
            'personal_emails': personal_emails,
            # Provenance for personal_emails. That list is written by BOTH workflow 09
            # (Flare's own 'associated emails' grouping — an inference) and workflow 27
            # (super-enrich, which vets the identity and sets this flag). Consumers that
            # attribute an off-corp address to a person need to tell those apart.
            'super_enriched': _is_true(props.get('super_enriched')),
            'flare_run': flare_run,
            'cred_count': len(my_creds),
            'validated_cred_count': validated_cred_count,
            'cred_severity': cred_severity,
            'cred_services': cred_services,
            'cred_types': cred_types,
            'has_reuse': has_reuse,
            'breach_cred_match': breach_cred_match,
            'confirmed_compromised': confirmed_compromised,
            'manages_assets': [a['label'] for a in my_assets],
            'linkedin_url':       _li.get('url') or None,
            'linkedin_job_title': _li.get('job_title'),
            'linkedin_employer':  _li.get('employer'),
            'tech_stack':         tech_stack,
            'tech_risk_score':    tech_risk_score,
            'os_risk':            os_risk,
            'relevant_cves':      relevant_cves,
            'mitre_techniques':   mitre_techniques,
        })

    individuals.sort(key=lambda x: -x['score'])

    # Operator-tagged people must reach the LLM even when the heuristic ranking
    # buries them: take the top N by score, then pull in any tagged individual that
    # missed the cut (bounded, so the prompt stays small). With no tags in play this
    # returns exactly ranked[:base_n].
    def _with_tagged(ranked, base_n, extra_cap):
        return ranked[:base_n] + [x for x in ranked[base_n:]
                                  if x.get('op_compromised') or x.get('op_of_interest')][:extra_cap]

    focus        = _with_tagged(individuals, 8, 6)   # prompt + intel blocks
    prompt_focus = _with_tagged(individuals, 6, 4)   # the LLM's target lines
    # The RESPONSE carries a far wider slice than the prompt: the card and its
    # drilldown are the operator's list, not the model's context budget. It stays
    # bounded (the browser keeps every analysis record in localStorage), so the
    # true totals ride along with it and the UI can say 'showing X of Y' instead
    # of implying the slice IS the ranking.
    _RESP_CAP    = 40
    resp_focus   = _with_tagged(individuals, _RESP_CAP, 6)

    # ── Score devices / computers (AD systems) as targets ────────────────────
    _OS_EOL_DB = [
        ('windows xp', 'Windows XP', '2014-04-08'), ('windows vista', 'Windows Vista', '2017-04-11'),
        ('windows 7', 'Windows 7', '2020-01-14'), ('windows 8.1', 'Windows 8.1', '2023-01-10'),
        ('windows 8', 'Windows 8', '2016-01-12'), ('windows 10', 'Windows 10', '2025-10-14'),
        ('windows 11', 'Windows 11', None),
        ('windows server 2003 r2', 'Windows Server 2003 R2', '2015-07-14'),
        ('windows server 2003', 'Windows Server 2003', '2015-07-14'),
        ('windows server 2008 r2', 'Windows Server 2008 R2', '2020-01-14'),
        ('windows server 2008', 'Windows Server 2008', '2020-01-14'),
        ('windows server 2012 r2', 'Windows Server 2012 R2', '2023-10-10'),
        ('windows server 2012', 'Windows Server 2012', '2023-10-10'),
        ('windows server 2016', 'Windows Server 2016', '2027-01-12'),
        ('windows server 2019', 'Windows Server 2019', '2029-01-09'),
        ('windows server 2022', 'Windows Server 2022', '2031-10-13'),
    ]
    def _classify_os(os_str):
        raw = (os_str or '').lower()
        for key, name, eol in _OS_EOL_DB:
            if key in raw:
                return name, eol
        return (os_str or 'Unknown'), None
    def _os_risk_of(eol_date_str):
        if not eol_date_str:
            return 'supported'
        from datetime import date, datetime
        eol = datetime.strptime(eol_date_str, '%Y-%m-%d').date()
        today = date.today()
        if eol >= today:
            return 'low' if (eol - today).days <= 180 else 'supported'
        dp = (today - eol).days
        if dp > 3 * 365: return 'critical'
        if dp > 365:     return 'high'
        return 'medium'
    _DEV_ACE_TYPES = {
        'GenericAll', 'WriteDacl', 'WriteOwner', 'GenericWrite', 'Owns',
        'ReadLAPSPassword', 'WriteAccountRestrictions', 'AllExtendedRights',
        'AddKeyCredentialLink', 'WriteSPN',
    }
    _dev_profiles = {}
    for _dn in nds:
        if (_dn.get('nodeType') or '').lower() not in ('device', 'computer'):
            continue
        _dp = _dn.get('nodeProperties') or {}
        _os_name, _eol = _classify_os(_dp.get('operating_system', ''))
        _stored = (_dp.get('os_risk') or '').lower()
        _risk = _stored if _stored in ('supported', 'low', 'medium', 'high', 'critical') else _os_risk_of(_eol)
        _hn = _dp.get('hostname') or _dn.get('nodeLabel', '')
        _display = _hn if (_hn and not str(_hn).startswith('S-1-')) else _dn.get('nodeLabel', _hn)
        # Device marks are keyed by the hostname shown in the Targets tab; also try
        # the SAM account (with and without the trailing $) and the short name.
        _sam = str(_dp.get('sam_account_name') or _dp.get('samaccountname') or '')
        _dal = {str(_x).strip().lower() for _x in (
            _display, _dn.get('nodeLabel'), _sam, _sam.rstrip('$'),
            str(_display).split('.')[0]) if _x}
        _dhit_oos  = _dal & _opd_oos_set
        _dhit_fp   = _dal & _opd_fp_set
        if _dhit_oos or _dhit_fp:
            _opd_oos_matched |= _dhit_oos
            _opd_fp_matched  |= _dhit_fp
            continue   # excluded host: not scored, not output
        _dhit_comp = _dal & _opd_comp_set
        _dhit_oi   = _dal & _opd_oi_set
        _opd_matched |= _dhit_comp | _dhit_oi
        _dev_profiles[_dn['id']] = {
            'hostname': _display, 'os': _os_name, 'os_risk': _risk, 'is_eol': bool(_eol),
            'op_compromised': bool(_dhit_comp), 'op_of_interest': bool(_dhit_oi),
            'is_dc': bool(_dp.get('is_dc')),
            'unconstrained_delegation': bool(_dp.get('unconstrained_delegation')),
            'constrained_delegation': bool(_dp.get('constrained_delegation')),
            'sessions': [], 'admins': [], 'aces': [],
        }
    for _de in rls:
        _el, _s, _t = _de.get('label', ''), _de.get('source', ''), _de.get('target', '')
        if _el == 'HAS_SESSION':
            _dv = _dev_profiles.get(_t); _ot = _s
            if _dv is None:
                _dv = _dev_profiles.get(_s); _ot = _t
            if _dv is not None:
                _on = nodes_by_id.get(_ot, {})
                if (_on.get('nodeType') or '').lower() == 'individual':
                    _ul = _on.get('nodeLabel', '')
                    if _ul and _ul not in _dv['sessions']:
                        _dv['sessions'].append(_ul)
        elif _el == 'LOCAL_ADMIN':
            _dv = _dev_profiles.get(_t)
            if _dv is not None:
                # Count every local admin but carry at most 30 names: the count is
                # what the card shows, the names are what the drilldown lists.
                _dv['admins_total'] = _dv.get('admins_total', 0) + 1
                if len(_dv['admins']) < 30:
                    _dv['admins'].append(nodes_by_id.get(_s, {}).get('nodeLabel', '') or _s)
        elif _el in _DEV_ACE_TYPES:
            _dv = _dev_profiles.get(_t)
            if _dv is not None and len(_dv['aces']) < 30:
                _dv['aces'].append({'principal': nodes_by_id.get(_s, {}).get('nodeLabel', '') or _s, 'ace': _el})
    # Sessions and local admins ship as NAMES beside their counts, so the count on
    # the Analysis card expands into who those principals actually are instead of
    # dead-ending on a number. Each name is enriched from the already-scored
    # individuals (score + flags) so the operator sees at a glance which of them is
    # a DA, an admin, or already owned. A principal that is not a scored individual
    # (a group holding local admin, say) comes through as a bare name.
    _ind_by_label = {_i['label']: _i for _i in individuals}
    _PRINC_FLAGS = ('is_admin', 'in_da', 'op_compromised', 'op_of_interest',
                    'has_beacon', 'confirmed_compromised', 'has_stealer')
    _PRINC_CAP = 50   # bounds the payload; the count beside the list stays exact
    def _princ(_lbl):
        _ip = _ind_by_label.get(_lbl)
        if not _ip:
            return {'name': _lbl}
        _o = {'name': _lbl, 'score': _ip.get('score', 0)}
        for _k in _PRINC_FLAGS:
            if _ip.get(_k):
                _o[_k] = True
        return _o
    device_targets = []
    for _dv in _dev_profiles.values():
        _sc = 15 if _dv['is_dc'] else 0
        _sc += {'critical': 10, 'high': 7, 'medium': 4, 'low': 2}.get(_dv['os_risk'], 0)
        if _dv['unconstrained_delegation']: _sc += 10
        if _dv['constrained_delegation']:   _sc += 5
        _sc += min(len(_dv['sessions']), 10)
        _sc += min(len(_dv['admins']) * 2, 10)
        _sc += min(len(_dv['aces']), 8)
        # Operator judgement on a host, same as for people: a marked box is either
        # already ours or a stated priority.
        _sc += (25 if _dv['op_compromised'] else 0) + (10 if _dv['op_of_interest'] else 0)
        _rs = []
        if _dv['op_compromised']: _rs.append('OPERATOR-MARKED COMPROMISED')
        if _dv['op_of_interest']: _rs.append('OPERATOR-MARKED OF INTEREST')
        if _dv['is_dc']: _rs.append('Domain Controller')
        if _dv['is_eol'] and _dv['os_risk'] in ('critical', 'high', 'medium', 'low'):
            _rs.append(f"EOL OS ({_dv['os']}, risk {_dv['os_risk']})")
        elif _dv['os'] and _dv['os'] != 'Unknown':
            _rs.append(_dv['os'])
        if _dv['unconstrained_delegation']: _rs.append('unconstrained delegation')
        if _dv['constrained_delegation']:   _rs.append('constrained delegation')
        if _dv['sessions']: _rs.append(f"{len(_dv['sessions'])} user session(s)")
        if _dv['admins']:   _rs.append(f"{_dv.get('admins_total', len(_dv['admins']))} local admin(s)")
        if _dv['aces']:     _rs.append(f"{len(_dv['aces'])} inbound ACE(s)")
        device_targets.append({
            'name': _dv['hostname'], 'score': _sc,
            'rationale': ', '.join(_rs) if _rs else 'AD computer',
            'op_compromised': _dv['op_compromised'], 'op_of_interest': _dv['op_of_interest'],
            'is_dc': _dv['is_dc'], 'os': _dv['os'], 'os_risk': _dv['os_risk'],
            'sessions': len(_dv['sessions']),
            'admins': _dv.get('admins_total', len(_dv['admins'])),
            'session_users': [_princ(_u) for _u in _dv['sessions'][:_PRINC_CAP]],
            'admin_users':   [_princ(_u) for _u in _dv['admins'][:_PRINC_CAP]],
            'unconstrained_delegation': _dv['unconstrained_delegation'],
            'constrained_delegation': _dv['constrained_delegation'],
        })
    device_targets.sort(key=lambda z: -z['score'])
    _device_all    = device_targets            # full ranking, before the prompt cap
    device_targets = _with_tagged(_device_all, _RESP_CAP, 6)
    _dev_lines = []
    for _i, _dv in enumerate(_with_tagged(device_targets, 6, 4), 1):
        _tags = []
        if _dv['op_compromised']: _tags.append('OPERATOR-COMPROMISED')
        if _dv['op_of_interest']: _tags.append('OPERATOR-OI')
        if _dv['is_dc']: _tags.append('DC')
        if _dv['unconstrained_delegation']: _tags.append('UNCONSTRAINED-DELEG')
        if _dv['constrained_delegation']:   _tags.append('CONSTRAINED-DELEG')
        if _dv['os_risk'] in ('critical', 'high'): _tags.append('EOL-OS:' + _dv['os_risk'].upper())
        _dev_lines.append(f"{_i}. {_dv['name']} [{'/'.join(_tags) if _tags else 'host'}] | OS:{_dv['os']} | sessions:{_dv['sessions']} | local_admins:{_dv['admins']}")
    device_block = '\n'.join('- ' + _l for _l in _dev_lines) if _dev_lines else 'No AD computers ingested yet.'

    # ── Build external attack-surface summary for the prompt + response ───────
    attack_surface = []
    for _aid, _a in assets_by_id.items():
        _p = _a['props']
        # Honour exclusion marks on external assets. They share the device mark
        # namespace (buckets keyed by bucket/endpoint, web by url, subdomain by
        # fqdn, service by ip — the same keys the Assets tab / recon panel use), so
        # an excluded bucket is dropped from the attack surface the LLM reasons over.
        _acand = {str(_x).strip().lower() for _x in (
            _a.get('label'), _p.get('bucket'), _p.get('endpoint'), _p.get('url'),
            _p.get('fqdn'), _p.get('hostname'), _p.get('name'), _p.get('ip')) if _x}
        _ahit_oos = _acand & _opd_oos_set
        _ahit_fp  = _acand & _opd_fp_set
        if _ahit_oos or _ahit_fp:
            # Credit the match. Until 2026-09-07 this branch dropped the asset
            # without recording it, so operator_tags.out_of_scope.excluded silently
            # omitted every excluded ASSET and an operator who marked a bucket read
            # "0 excluded" and could not tell whether the mark had landed.
            _opd_oos_matched |= _ahit_oos
            _opd_fp_matched  |= _ahit_fp
            continue
        try:
            _vv = _p.get('vulns'); _vlist = json.loads(_vv) if isinstance(_vv, str) else (_vv or [])
        except Exception:
            _vlist = []
        try:
            _mc = _p.get('manager_candidates'); _mcl = json.loads(_mc) if isinstance(_mc, str) else (_mc or [])
        except Exception:
            _mcl = []
        attack_surface.append({
            'type':       _a['type'],
            'label':      _a['label'],
            'platform':   _p.get('platform') or _p.get('service') or '',
            'is_wordpress': bool(_p.get('is_wordpress')) or (str(_p.get('platform') or '').lower() == 'wordpress'),
            'vulns':      _vlist[:8] if isinstance(_vlist, list) else [],
            'open_ports': _p.get('open_ports') or '',
            'owners':     [o for o in asset_owner_names.get(_aid, [])
                           if o and o.lower() not in _op_oos_set and o.lower() not in _op_fp_set],
            # Every spelling this asset is known by. The browser keys its marks off
            # whichever one the surface in front of the operator shows (the Web tab
            # has the url, the bucket list the endpoint, this card the graph label),
            # so shipping the set lets a mark made here match all of them.
            'keys':       sorted(_acand),
            'manager_candidates': [(c.get('name') if isinstance(c, dict) else c) for c in (_mcl if isinstance(_mcl, list) else [])][:5],
        })
    attack_surface.sort(key=lambda x: (-(len(x['owners']) > 0), -len(x['vulns'])))
    _surface_lines = []
    for _s in attack_surface[:10]:
        _bits = [_s['type'], _s['label']]
        if _s.get('is_wordpress'): _bits.append('WordPress')
        elif _s.get('platform'):   _bits.append(_s['platform'])
        if _s.get('vulns'):        _bits.append('vulns:' + ','.join(str(v) for v in _s['vulns'][:3]))
        if _s.get('owners'):       _bits.append('managed_by:' + ','.join(_s['owners'][:3]))
        elif _s.get('manager_candidates'): _bits.append('likely_mgr:' + ','.join(str(c) for c in _s['manager_candidates'][:3]))
        _surface_lines.append(' | '.join(str(b) for b in _bits if b))
    surface_block = '\n'.join('- ' + _l for _l in _surface_lines) if _surface_lines else 'No external assets ingested from Domain Recon yet.'

    # Pre-built targets list — scoring is deterministic, no LLM needed here
    pretargets = [{
        'name':            ind['label'],
        'score':           ind['score'],
        'rationale':       ind['rationale'],
        'op_compromised':  ind.get('op_compromised', False),
        'op_of_interest':  ind.get('op_of_interest', False),
        'is_admin':        ind['is_admin'],
        'breach_count':    ind.get('breach_count', 0),
        'has_stealer':     ind.get('has_stealer', False),
        'cred_count':            ind.get('cred_count', 0),
        'validated_cred_count':  ind.get('validated_cred_count', 0),
        'confirmed_compromised': ind.get('confirmed_compromised', False),
        'breach_cred_match':     ind.get('breach_cred_match', False),
        'has_reuse':             ind.get('has_reuse', False),
        'manages_assets':  ind.get('manages_assets') or [],
        'personal_emails': ind.get('personal_emails') or [],
        'linkedin_url':       ind.get('linkedin_url'),
        'linkedin_job_title': ind.get('linkedin_job_title'),
        'linkedin_employer':  ind.get('linkedin_employer'),
    } for ind in resp_focus]

    # ── SHORT prompt to Analysis LLM: only scenarios + summary ────────────────────
    # Top 6 targets as compact one-liners (minimise input tokens)
    top6_lines = []
    for i, ind in enumerate(prompt_focus, 1):
        tags = []
        if ind.get('op_compromised'): tags.append('OPERATOR-COMPROMISED')
        if ind.get('op_of_interest'): tags.append('OPERATOR-OI')
        if ind['is_admin']:    tags.append('ADMIN')
        if ind['in_da']:       tags.append('DA')
        if ind['has_beacon']:  tags.append('BEACON')
        if ind['has_stealer']: tags.append('STEALER')
        if ind.get('validated_cred_count'): tags.append('CONFIRMED-CRED')
        elif ind.get('cred_count'):         tags.append('CRED')
        if ind.get('breach_cred_match'):    tags.append('BREACH-x-CRED')
        if ind.get('has_reuse'):            tags.append('PW-REUSE')
        ace_note = f" | ACE:{ind['top_ace']['right']} on {ind['top_ace']['target']}" if ind['top_ace'] else ''
        pe = ind.get('personal_emails') or []
        pe_note = f" | personal:{pe[0]}" if pe else ''
        # Credential-to-user detail: count, how many are validated (confirmed
        # compromised), and which services they unlock.
        cred_note = ''
        if ind.get('cred_count'):
            _cp = str(ind['cred_count'])
            if ind.get('validated_cred_count'):
                _cp += f"/{ind['validated_cred_count']}-validated"
            _svcs = ind.get('cred_services') or ind.get('cred_types') or []
            if _svcs:
                _cp += ':' + ','.join(_svcs[:3])
            cred_note = f" | creds:{_cp}"
        breach_note = ''
        if ind.get('breach_events'):
            breach_note = ' | breach:' + ','.join(f"{k}x{v}" for k, v in ind['breach_events'].items())
            _mal = ind.get('stealer_malware') or []
            if _mal:
                breach_note += f"[{','.join(_mal[:2])}]"
        if ind.get('plaintext_exposed'):
            breach_note += ' PLAINTEXT-PW'
        _li_hint = ind.get('linkedin_job_title') or ind.get('linkedin_employer')
        li_note = f' | LI:{_li_hint}' if _li_hint else ''
        _tech_note = f" | tech_risk:{ind['tech_risk_score']:.0f}" if ind.get('tech_risk_score', 0) > 0 else ''
        _cve_note = f" | CVEs:{len(ind['relevant_cves'])}" if ind.get('relevant_cves') else ''
        top6_lines.append(f"{i}. {ind['label']} [{'/'.join(tags) if tags else 'user'}]{ace_note}{cred_note}{breach_note}{pe_note}{li_note}{_tech_note}{_cve_note}")

    # ── Campaign Objectives — the PRIMARY analysis criteria ───────────────────────
    # Full objectives are injected into the system prompt so the LLM correlates the
    # ingested intelligence against the assessment goals — not just raw AD scores.
    mission_text = (mission_statement or 'No mission statement specified.').strip()[:1200]
    obj_lines = [
        f'- Target type: {target_type or "unspecified"}',
        f'- Primary target: {target_name or "unspecified"}',
    ]
    if additional_ids:
        obj_lines.append(f'- Additional identifiers: {str(additional_ids)[:300]}')
    if company_email:
        obj_lines.append('- Company email: ' + company_email + (f' (domain: {company_domain})' if company_domain else ''))
    objectives_block = '\n'.join(obj_lines) + '\n- Mission, goals & rules of engagement: ' + mission_text

    # ── Technology risk summary for the prompt + response ───────────────────
    vulnerable_tech = []
    for node in nds:
        ntype = (node.get('nodeType') or '').lower()
        if ntype != 'technology':
            continue
        tp = node.get('nodeProperties') or {}
        cve_count = int(tp.get('cve_count') or 0)
        if cve_count or tp.get('is_high_value'):
            vulnerable_tech.append({
                'name': tp.get('name') or node.get('nodeLabel'),
                'vendor': tp.get('vendor'),
                'version': tp.get('version'),
                'cve_count': cve_count,
                'is_high_value': bool(tp.get('is_high_value')),
                'mitre_techniques': tp.get('mitre_techniques') or [],
                'composite_risk': tp.get('composite_risk'),
            })
    vulnerable_tech.sort(key=lambda x: -(x.get('cve_count') or 0))
    _vuln_lines = []
    for _v in vulnerable_tech[:10]:
        _bits = [_v['name']]
        if _v.get('version'): _bits.append(f"v{_v['version']}")
        if _v.get('cve_count'): _bits.append(f"{_v['cve_count']} CVEs")
        if _v.get('is_high_value'): _bits.append('HIGH-VALUE')
        _mt = _v.get('mitre_techniques') or []
        if _mt:
            _ids = [m.get('technique_id') if isinstance(m, dict) else str(m) for m in _mt[:3]]
            _bits.append('MITRE: ' + ','.join(_ids))
        _vuln_lines.append(' | '.join(str(b) for b in _bits if b))
    vuln_block = '\n'.join('- ' + _l for _l in _vuln_lines) if _vuln_lines else 'No CVE-mapped technology ingested yet.'

    # ── Compromised credentials & breach intelligence for the prompt + response ──
    # Correlates Flare breach records and Titus-scanned credentials to the top
    # targets so the LLM builds credential-based access paths, not just AD paths.
    _cred_lines = []
    for ind in focus:
        if not (ind.get('cred_count') or ind.get('breach_count') or ind.get('confirmed_compromised')):
            continue
        _bits = [ind['label']]
        if ind.get('validated_cred_count'):
            _bits.append(f"{ind['validated_cred_count']} CONFIRMED-COMPROMISED credential(s)")
        elif ind.get('cred_count'):
            _bits.append(f"{ind['cred_count']} credential(s) (unvalidated)")
        _svcs = ind.get('cred_services') or ind.get('cred_types') or []
        if _svcs:
            _bits.append('unlocks:' + ','.join(_svcs[:4]))
        if ind.get('breach_events'):
            _bits.append('breaches:' + ','.join(f"{k}x{v}" for k, v in ind['breach_events'].items()))
        if ind.get('stealer_malware'):
            _bits.append('stealer:' + ','.join(ind['stealer_malware'][:2]))
        if ind.get('breach_cred_match'):
            _bits.append('VALIDATED-CRED-x-CORP-BREACH')
        if ind.get('has_reuse'):
            _bits.append('PASSWORD-REUSE')
        if ind.get('plaintext_exposed'):
            _bits.append('PLAINTEXT-PASSWORD-EXPOSED')
        _cred_lines.append(' | '.join(str(b) for b in _bits))
    cred_block = ('\n'.join('- ' + _l for _l in _cred_lines) if _cred_lines
                  else 'No compromised credentials or breach records correlated to targets yet.')

    # ── Operator-tagged targets for the prompt + response ─────────────────────
    # Marks made by hand in the Targets tab. A tag that matched nobody is reported
    # back so the operator sees it was ignored instead of assuming it was honoured.
    _op_comp_names = [i['label'] for i in individuals if i.get('op_compromised')]
    _op_oi_names   = [i['label'] for i in individuals if i.get('op_of_interest')]
    _opd_comp_names = [d['name'] for d in _device_all if d.get('op_compromised')]
    _opd_oi_names   = [d['name'] for d in _device_all if d.get('op_of_interest')]
    _op_sent       = (_op_comp_set | _op_oi_set), (_opd_comp_set | _opd_oi_set)
    op_unmatched   = sorted(
        {_op_orig.get(k, k) for k in _op_sent[0] if k not in _op_matched} |
        {_opd_orig.get(k, k) for k in _op_sent[1] if k not in _opd_matched})
    _op_lines = []
    for ind in focus:
        if not (ind.get('op_compromised') or ind.get('op_of_interest')):
            continue
        _mark = ('COMPROMISED — operator-confirmed foothold, this account is already ours'
                 if ind.get('op_compromised')
                 else 'OF INTEREST — operator-designated priority')
        _op_lines.append(f"USER {ind['label']} | {_mark} | score {ind['score']} | {ind['rationale']}")
    for _dv in device_targets:
        if not (_dv.get('op_compromised') or _dv.get('op_of_interest')):
            continue
        _mark = ('COMPROMISED — operator-confirmed foothold, we already have code execution '
                 'or admin on this host'
                 if _dv.get('op_compromised')
                 else 'OF INTEREST — operator-designated priority')
        _op_lines.append(f"HOST {_dv['name']} | {_mark} | score {_dv['score']} | {_dv['rationale']}")
    if _op_lines:
        op_block = '\n'.join('- ' + _l for _l in _op_lines)
    elif _op_sent[0] or _op_sent[1]:
        op_block = ('The operator marked ' + str(len(_op_sent[0]) + len(_op_sent[1])) +
                    ' target(s) in the Targets tab, but none matched a user or computer in this '
                    'campaign graph. Treat the roster as untagged and say so.')
    else:
        op_block = 'The operator has not marked any targets Compromised or Of Interest in this campaign.'
    if _op_fp_matched or _opd_fp_matched:
        op_block += ('\n- The operator marked ' + str(len(_op_fp_matched) + len(_opd_fp_matched)) +
                     ' earlier result(s) FALSE POSITIVE. They have been removed from the data above '
                     'and are not available to you. Do not speculate about what they were.')

    system_prompt = (
        'You are SPOTTER, a red team intelligence analyst supporting an AUTHORIZED, scoped '
        'penetration test conducted under documented Rules of Engagement.\n\n'
        'The CAMPAIGN OBJECTIVES below are your PRIMARY analysis criteria. For every judgement, '
        'correlate the ingested intelligence (scored targets, AD privileges, compromised credentials, '
        'breach/OSINT data, technology risk) '
        'against these objectives and explain the relationship to the assessment goals.\n\n'
        '## CAMPAIGN OBJECTIVES\n' + objectives_block + '\n\n'
        '## OPERATOR-TAGGED TARGETS (hand-marked by the operator in the Targets tab)\n' + op_block + '\n\n'
        '## COMPROMISED CREDENTIALS & BREACH INTELLIGENCE (Flare breaches + Titus credential scans)\n' + cred_block + '\n\n'
        '## EXTERNAL ATTACK SURFACE (from Domain Recon)\n' + surface_block + '\n\n'
        '## VULNERABLE TECHNOLOGY (from Tech Intel)\n' + vuln_block + '\n\n'
        '## HIGH-VALUE SYSTEMS (AD computers: DCs, EOL OS, delegation)\n' + device_block + '\n\n'
        'Use the objectives, compromised credentials, and external attack surface to:\n'
        '1. Identify which ingested targets and data points are most relevant to the assessment goals, and why.\n'
        '2. Prioritize and rank targets by mission alignment, not just raw AD privilege.\n'
        '3. Produce attack scenarios that advance the stated mission goals.\n'
        '4. Respect the Rules of Engagement and flag any scenario that risks an ROE violation.\n'
        '5. Correlate the external attack surface and vulnerable technology with the people who manage or can access them (who owns an exposed WordPress site, cloud bucket, vulnerable service, or high-value software such as SAP, PAM, password managers, or terminal emulators) and build attack paths that pivot through those relationships.\n'
        '6. When a target has relevant CVEs, MITRE ATT&CK techniques, or high-value technology, incorporate those into the scenario chain and difficulty rating.\n'
        '7. Treat CONFIRMED-COMPROMISED credentials (validated by Titus) and VALIDATED-CRED-x-CORP-BREACH matches as the HIGHEST-CONFIDENCE initial-access opportunities. Build scenarios that use those credentials directly (authenticated access to the named service, credential stuffing / password spray with reused passwords, pass-the-hash for NTLM hashes) and rank the individuals who hold them at the top. Stealer-log and plaintext-password exposures indicate the password is likely still usable; cite the specific individual and service in the scenario chain.\n'
        '8. Factor in current AD attack primitives when building chains: Kerberoasting / AS-REP (crackable service or no-preauth accounts, RC4-first), unconstrained / constrained / RBCD delegation, ADCS ESC1 / ESC8 (arbitrary-SAN cert or web-enrollment relay), NTLM coercion + relay (PetitPotam / DFSCoerce), SID history, GPO abuse, and domain / forest trusts (child->root). Name the concrete tool as the exploitation step (Rubeus, Certipy, ntlmrelayx / krbrelayx, SharpGPOAbuse, Impacket).\n'
        '9. Prefer the STEALTHIEST edge that reaches the objective and note detection risk per step (DCSync is noisy, RC4 Kerberoast is detectable, coercion emits auth events, ADCS ESC1 is quiet); flag EDR/AMSI-heavy steps but do NOT generate implant or evasion payloads.\n'
        '10. The OPERATOR-TAGGED TARGETS section is human judgement from the live engagement and OUTRANKS the heuristic scores. Entries are prefixed USER (an account) or HOST (an AD computer). A target tagged COMPROMISED (also flagged OPERATOR-COMPROMISED in the target lines) is already under the team\'s control — an owned account, or a host with code execution / admin on it: start chains FROM it and spend the scenario on escalation, lateral movement and objective completion, not on re-acquiring initial access to it. A compromised HOST is a pivot point: reason about the sessions, local admins and cached credentials on that box, and about what it can reach. A target tagged OF INTEREST (OPERATOR-OI) is an operator priority: address it in the scenario set, or state plainly why it is not viable. If the ingested evidence contradicts a tag, say so instead of silently dropping it.\n\n'
        'Output ONLY a JSON object with keys: '
        '"objective_alignment" (2-3 sentences explaining how the ingested data relates to the campaign '
        'objectives and which targets best serve the mission), '
        '"scenarios" (array of 3 objects), and "summary" (2 sentences). '
        'Each scenario object has: "id" (SCENARIO-1/2/3), "name", "objective" (which campaign goal it '
        'advances), "chain" (step-by-step), "techniques" (array of ATT&CK IDs), "difficulty" (high/medium/low).'
    )

    user_prompt = (
        'Top scored targets from the ingested data (heuristic AD/OSINT scoring):\n'
        + '\n'.join(top6_lines) + '\n\n'
        'Analyze these targets strictly against the CAMPAIGN OBJECTIVES in your instructions. '
        'Return the JSON object described above.'
    )

    # ── breach + credential intel for the response (built once, reused below) ────
    # Filter FIRST, then cap. These two sections used to be built from the prompt
    # slice (top 8 + tagged), so a person ranked 20th by AD score with a stealer
    # log or a validated credential never appeared here at all — the section read
    # as 'nobody else is breached'. Now the whole ranking is filtered down to who
    # actually has records, and only then bounded to the response cap.
    _breach_pool = [ind for ind in individuals
                    if ind.get('breach_count', 0) > 0 or ind.get('has_stealer', False)]
    breach_intel = [
        {'name': ind['label'], 'breach_count': ind.get('breach_count', 0),
         'has_stealer': ind.get('has_stealer', False),
         'personal_emails': ind.get('personal_emails') or [],
         'breach_events': ind.get('breach_events') or {},
         'stealer_malware': ind.get('stealer_malware') or [],
         'plaintext_exposed': ind.get('plaintext_exposed', False),
         'super_enriched': ind.get('super_enriched', False),
         'breach_cred_match': ind.get('breach_cred_match', False)}
        for ind in _with_tagged(_breach_pool, _RESP_CAP, 6)
    ]
    _cred_pool = [ind for ind in individuals
                  if ind.get('cred_count', 0) > 0 or ind.get('validated_cred_count', 0) > 0]
    credential_intel = [
        {'name': ind['label'],
         'cred_count': ind.get('cred_count', 0),
         'validated_cred_count': ind.get('validated_cred_count', 0),
         'confirmed_compromised': ind.get('confirmed_compromised', False),
         'cred_severity': ind.get('cred_severity', ''),
         'cred_services': ind.get('cred_services') or [],
         'cred_types': ind.get('cred_types') or [],
         'has_reuse': ind.get('has_reuse', False),
         'breach_cred_match': ind.get('breach_cred_match', False),
         'super_enriched': ind.get('super_enriched', False),
         'plaintext_exposed': ind.get('plaintext_exposed', False)}
        for ind in _with_tagged(_cred_pool, _RESP_CAP, 6)
    ]
    # The two *_total counts above are of INDEPENDENTLY CAPPED, OVERLAPPING pools, so a
    # consumer cannot derive how many distinct people are exposed — only bound it at
    # max(bT,cT) <= n <= bT+cT. Ship the real number so the UI need not print a range.
    _exposure_total = len({i['label'] for i in _breach_pool} | {i['label'] for i in _cred_pool})

    # Echoed back so the operator can see which marks the analysis actually used —
    # a tag keyed to a label that no longer exists in the graph matches nothing.
    operator_tags_out = {
        'compromised': _op_comp_names,
        'of_interest': _op_oi_names,
        'devices': {'compromised': _opd_comp_names, 'of_interest': _opd_oi_names},
        'sent': len(_op_sent[0]) + len(_op_sent[1]),
        'matched': len(_op_matched) + len(_opd_matched),
        'unmatched': op_unmatched[:50],
        # Out-of-scope entities dropped before scoring, echoed back so the operator
        # can confirm the exclusion took effect. A mark that matched nothing is
        # simply absent here.
        'out_of_scope': {
            'individuals': sorted({_op_oos_orig.get(k, k) for k in _op_oos_matched}),
            'devices':     sorted({_opd_oos_orig.get(k, k) for k in _opd_oos_matched}),
            'sent':     len(_op_oos_set) + len(_opd_oos_set),
            'excluded': len(_op_oos_matched) + len(_opd_oos_matched),
        },
        'false_positive': {
            'individuals': sorted({_op_fp_orig.get(k, k) for k in _op_fp_matched}),
            'devices':     sorted({_opd_fp_orig.get(k, k) for k in _opd_fp_matched}),
            'sent':     len(_op_fp_set) + len(_opd_fp_set),
            'excluded': len(_op_fp_matched) + len(_opd_fp_matched),
            # A mark that matched nothing is weightless. out_of_scope has never
            # reported this, so an operator cannot tell a typo'd mark from a
            # correctly-honoured one; false_positive reports it from the start.
            'unmatched': sorted(
                {_op_fp_orig.get(k, k)  for k in _op_fp_set  if k not in _op_fp_matched} |
                {_opd_fp_orig.get(k, k) for k in _opd_fp_set if k not in _opd_fp_matched})[:50],
        },
    }

    # ── call Analysis LLM via llm-gateway -> vLLM (format:"json") ─────────────────────────────
    # NOTE: default model is qwen3.8:27b (see SECURITY_LLM_MODEL above and in .env) — this
    # comment claimed qwen3:8b for a long time while the code two dozen lines up defaulted to
    # something else, so trust the assignment, not prose. The earlier qwen3.5:9b tag emitted
    # empty/whitespace-only output (unsupported arch), which is the failure to expect if this
    # is ever repointed at a tag Ollama loads but cannot decode. Ollama JSON-schema 'format'
    # produced empty output here, so we use the plain 'json' mode and parse defensively below.
    # num_predict/num_ctx are sized to the MODEL, not to taste. Measured 2026-08-14 on this
    # exact prompt (~1,680 prompt tokens): qwen3:8b finishes the JSON in 751 tokens, but both
    # 27b models run 1,000+ and were being cut off at the old num_predict=800 — Ollama returns
    # done_reason="length", the JSON ends mid-string, and the salvage regex below recovers
    # objective_alignment and a couple of scenarios while "summary" silently comes back empty.
    # That degrades quietly instead of erroring, so it is easy to miss. 1600 leaves headroom
    # (observed 1,015). num_ctx must cover prompt + num_predict: at the old 3072 there was no
    # room for a 1600-token completion. If you change the model, re-measure — check
    # done_reason is "stop", not "length".
    try:
        llm_r = req.post(
            f'{OLLAMA_URL}/api/chat',
            json={
                'model': SEC_LLM_MODEL,
                'format': 'json',
                # qwen3 is a hybrid *thinking* model; disable thinking so it emits
                # the JSON directly (clean output, no wasted CPU tokens). Ignored by
                # non-thinking models (e.g. SecurityLLM).
                'think': False,
                'messages': [
                    {'role': 'system', 'content': system_prompt},
                    {'role': 'user',   'content': user_prompt},
                ],
                'stream': False,
                'options': {
                    'temperature': 0.2,
                    'num_predict': 1600,
                    'num_ctx': 8192,
                },
            },
            timeout=360,
        )
        llm_r.raise_for_status()
        content = llm_r.json().get('message', {}).get('content') or ''
    except Exception as e:
        return [{'json': {
            'error': f'Analysis LLM call failed: {e}',
            'targets': pretargets,
            'targets_total': len(individuals),
            'device_targets': device_targets,
            'device_targets_total': len(_device_all),
            'attack_surface': attack_surface,
            'objective_alignment': '',
            'scenarios': [],
            'summary': f'LLM unavailable. {len(individuals)} individuals scored by SPOTTER heuristics.',
            'campaign_id': campaign_id,
            'individuals_count': len(individuals),
            'vulnerable_tech': vulnerable_tech,
            'breach_intel': breach_intel,
            'breach_intel_total': len(_breach_pool),
            'credential_intel': credential_intel,
            'credential_intel_total': len(_cred_pool),
            'exposure_total': _exposure_total,
            'operator_tags': operator_tags_out,
        }}]

    # ── parse response — schema yields valid JSON; still repair defensively ────
    def _parse_llm_json(txt):
        """Best-effort parse that repairs truncated/whitespace-padded LLM output."""
        if not txt or not txt.strip():
            return {}
        try:
            return json.loads(txt)
        except Exception:
            pass
        s = txt.strip()
        _i = s.find('{')
        if _i > 0:
            s = s[_i:]
        stack, in_str, esc = [], False, False
        for ch in s:
            if in_str:
                if esc: esc = False
                elif ch == '\\': esc = True
                elif ch == '"': in_str = False
                continue
            if ch == '"': in_str = True
            elif ch in '{[': stack.append(ch)
            elif ch in '}]':
                if stack: stack.pop()
        repaired = s.rstrip()
        if repaired.endswith(','):
            repaired = repaired[:-1]
        if in_str:
            repaired += '"'
        for ch in reversed(stack):
            repaired += ']' if ch == '[' else '}'
        try:
            return json.loads(repaired)
        except Exception:
            d = {}
            m = re.search(r'"objective_alignment"\s*:\s*"((?:[^"\\]|\\.)*)"', s)
            if m: d['objective_alignment'] = m.group(1)
            m2 = re.search(r'"summary"\s*:\s*"((?:[^"\\]|\\.)*)"', s)
            if m2: d['summary'] = m2.group(1)
            return d

    llm_data = _parse_llm_json(content)
    if isinstance(llm_data, list):
        llm_data = {'scenarios': llm_data}
    if not isinstance(llm_data, dict):
        llm_data = {}
    _scen = llm_data.get('scenarios') or []
    if not isinstance(_scen, list):
        _scen = []
    def _as_text(v):
        if v is None: return ''
        if isinstance(v, str): return v
        try: return json.dumps(v)
        except Exception: return str(v)
    result = {
        'targets':             pretargets,
        'targets_total':       len(individuals),
        'device_targets':      device_targets,
        'device_targets_total': len(_device_all),
        'attack_surface':      attack_surface,
        'vulnerable_tech':     vulnerable_tech,
        'objective_alignment': _as_text(llm_data.get('objective_alignment', '')),
        'scenarios':           _scen,
        'summary':             _as_text(llm_data.get('summary', '')),
        'individuals_count':   len(individuals),
        'campaign_id':         campaign_id,
        'breach_intel':        breach_intel,
        'breach_intel_total':  len(_breach_pool),
        'credential_intel':    credential_intel,
        'credential_intel_total': len(_cred_pool),
        'exposure_total':      _exposure_total,
        'operator_tags':       operator_tags_out,
    }
    # Only if NOTHING usable was produced do we flag an error (frontend can still
    # show the heuristic targets + attempt raw recovery).
    if not result['objective_alignment'] and not result['scenarios'] and not result['summary']:
        result['error'] = 'Unexpected LLM response format.'
        result['raw_response'] = content[:500]
    try:
        from analysis_history import record_run
        result['analysis_run_id'] = record_run(SKETCH_ID, 'wf10', {'campaign_id': campaign_id, 'target_name': target_name, 'mission_statement': mission_statement}, result)
    except Exception:
        pass
    return [{'json': result}]
except Exception as _top_err:
    return [{'json': {
        'error': f'Workflow crashed: {repr(_top_err)}',
        'targets': [], 'device_targets': [], 'scenarios': [], 'summary': '',
        'individuals_count': 0, 'breach_intel': [], 'credential_intel': [], 'vulnerable_tech': [],
    }}]
# _TOP_LEVEL_GUARD_
